-- images 6750-6765
insert into public.product_images (product_id, path, alt, position, is_cover)
select p.id, x->>'path', x->>'alt', coalesce((x->>'position')::int, 0), coalesce((x->>'is_cover')::boolean, false)
from jsonb_array_elements($json$[{"sku":"SU-1000030","path":"/media/SU-1000030/09-x30.jpg","position":8,"is_cover":false,"alt":"Ordinateur de plongée sous-marine DESCENT™ X30 GARMIN"},{"sku":"SU-1000030","path":"/media/SU-1000030/10-x301.jpg","position":9,"is_cover":false,"alt":"Ordinateur de plongée sous-marine DESCENT™ X30 GARMIN"},{"sku":"SU-1000030","path":"/media/SU-1000030/11-307.jpg","position":10,"is_cover":false,"alt":"Ordinateur de plongée sous-marine DESCENT™ X30 GARMIN"},{"sku":"SU-1000030","path":"/media/SU-1000030/12-304.jpg","position":11,"is_cover":false,"alt":"Ordinateur de plongée sous-marine DESCENT™ X30 GARMIN"},{"sku":"SU-1000030","path":"/media/SU-1000030/13-305.jpg","position":12,"is_cover":false,"alt":"Ordinateur de plongée sous-marine DESCENT™ X30 GARMIN"},{"sku":"SU-1000030","path":"/media/SU-1000030/14-306.jpg","position":13,"is_cover":false,"alt":"Ordinateur de plongée sous-marine DESCENT™ X30 GARMIN"},{"sku":"SU-1000030","path":"/media/SU-1000030/15-301.jpg","position":14,"is_cover":false,"alt":"Ordinateur de plongée sous-marine DESCENT™ X30 GARMIN"},{"sku":"SU-1000030","path":"/media/SU-1000030/16-302.jpg","position":15,"is_cover":false,"alt":"Ordinateur de plongée sous-marine DESCENT™ X30 GARMIN"},{"sku":"TE-0003488","path":"/media/TE-0003488/01-qk_1.jpg","position":0,"is_cover":true,"alt":"Sac de voyage duffle bag SEA STASH jaune QUIKSILVER"},{"sku":"TE-0003488","path":"/media/TE-0003488/02-50183f8e-7aed-4aa9-b346-226c9fc22148_1_1.jpg","position":1,"is_cover":false,"alt":"Sac de voyage duffle bag SEA STASH jaune QUIKSILVER"},{"sku":"TE-0003488","path":"/media/TE-0003488/03-helly-hansen-hh-duffel-bag-2-30l-ocean-22840_328542_22840.jpg","position":2,"is_cover":false,"alt":"Sac de voyage duffle bag SEA STASH jaune QUIKSILVER"},{"sku":"TE-0003488","path":"/media/TE-0003488/04-qk4_1.jpg","position":3,"is_cover":false,"alt":"Sac de voyage duffle bag SEA STASH jaune QUIKSILVER"},{"sku":"TE-0003488","path":"/media/TE-0003488/05-qk1_1.jpg","position":4,"is_cover":false,"alt":"Sac de voyage duffle bag SEA STASH jaune QUIKSILVER"},{"sku":"TE-0003488","path":"/media/TE-0003488/06-qk5_1.jpg","position":5,"is_cover":false,"alt":"Sac de voyage duffle bag SEA STASH jaune QUIKSILVER"},{"sku":"TE-0003488","path":"/media/TE-0003488/07-qk2_2.jpg","position":6,"is_cover":false,"alt":"Sac de voyage duffle bag SEA STASH jaune QUIKSILVER"}]$json$) as x
join public.products p on p.sku = x->>'sku'
on conflict (product_id, path) do update set
  alt = excluded.alt,
  position = excluded.position,
  is_cover = excluded.is_cover;
